parameters.jsCode:
let r = {};
try {
  r = JSON.parse($json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}');
} catch (e) { r = {}; }

const CATS = ['data_discrepancy','connector_auth','api_error','billing','other'];
const PRIS = ['urgent','high','normal','low'];
const is_valid = CATS.includes(r.category) && PRIS.includes(r.priority)
  && typeof r.confidence === 'number' && r.confidence >= 0 && r.confidence <= 1;

return {
  ticket_id: $('Save ticket').item.json.id,
  category: is_valid ? r.category : null,
  priority: is_valid ? r.priority : null,
  confidence: is_valid ? r.confidence : null,
  reasoning: r.reasoning ?? null,
  is_valid,
  raw_response: JSON.stringify($json),
  model: $json.modelVersion,
  input_tokens: $json.usageMetadata?.promptTokenCount,
  output_tokens: $json.usageMetadata?.candidatesTokenCount,
};

parameters.jsonBody:
={{ JSON.stringify({
  systemInstruction: { parts: [{ text: `You triage support tickets for a marketing data platform that pulls data from ad platforms (Meta Ads, Google Ads, GA4, TikTok) into a warehouse and dashboards. Classify the ticket.

Categories:
- data_discrepancy: numbers differ from the source platform, or data is missing or delayed
- connector_auth: a connection failed because of login, OAuth, expired token or permissions
- api_error: extraction or API failures, rate limits, timeouts, error codes, schema changes
- billing: invoices, payments, plan or pricing
- other: anything else

Priority:
- urgent: pipeline down for many accounts, or business-critical impact today
- high: a connector or report is broken and blocking the customer
- normal: partial issue or question with a workaround
- low: how-to questions, feature requests

Confidence: 0 to 1, how sure you are about the category. Go below 0.6 if the ticket is vague or fits several categories. Reasoning: one short sentence.` }] },
  contents: [{ role: "user", parts: [{ text: "Subject: " + $('Webhook').item.json.body.subject + "\n\n" + $('Webhook').item.json.body.body }] }],
  generationConfig: {
    temperature: 0,
    responseMimeType: "application/json",
    responseSchema: {
      type: "OBJECT",
      properties: {
        category: { type: "STRING", enum: ["data_discrepancy","connector_auth","api_error","billing","other"] },
        priority: { type: "STRING", enum: ["urgent","high","normal","low"] },
        confidence: { type: "NUMBER" },
        reasoning: { type: "STRING" }
      },
      required: ["category","priority","confidence","reasoning"]
    }
  }
}) }}

={{ JSON.stringify({
  systemInstruction: { parts: [{ text: `You draft replies for support agents at a marketing data platform (pulls Meta Ads, Google Ads, GA4 etc. into dashboards). A human reviews every draft before sending.

Rules:
- Use ONLY the KB articles provided. Never invent causes, features, fixes or timelines.
- If the articles don't clearly cover the issue, set is_unsure to true. The reply should then acknowledge the issue, ask for the specific details needed, and say the team will investigate.
- Ask for concrete details when relevant: account or property IDs, date range, exact numbers, error text.
- Friendly, clear, concise. No promises about fix dates.
- used_article_ids: ids of the articles you actually relied on.` }] },
  contents: [{ role: "user", parts: [{ text:
    "TICKET\nSubject: " + $('Webhook').item.json.body.subject + "\n\n" + $('Webhook').item.json.body.body +
    "\n\nCATEGORY: " + $('Save classification').item.json.category +
    "\n\nKB ARTICLES:\n" + ($('KB lookup').item.json.articles.map(a => "[" + a.id + "] " + a.title + "\n" + a.body).join("\n\n") || "No matching articles found.")
  }] }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: "application/json",
    responseSchema: {
      type: "OBJECT",
      properties: {
        reply: { type: "STRING" },
        is_unsure: { type: "BOOLEAN" },
        used_article_ids: { type: "ARRAY", items: { type: "INTEGER" } }
      },
      required: ["reply", "is_unsure", "used_article_ids"]
    }
  }
}) }}

parameters.jsCode:
let d = {};
try {
  d = JSON.parse($json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}');
} catch (e) { d = {}; }

return {
  reply: d.reply ?? null,
  // no reply at all counts as unsure too
  is_unsure: d.is_unsure === true || !d.reply,
  used_article_ids: Array.isArray(d.used_article_ids) ? d.used_article_ids.filter(Number.isInteger) : [],
  model: $json.modelVersion,
  input_tokens: $json.usageMetadata?.promptTokenCount,
  output_tokens: $json.usageMetadata?.candidatesTokenCount,
};

const c = $('Save classification').item.json;
const reasons = [];

if (!c.is_valid) reasons.push('invalid_classification');
if (c.confidence !== null && Number(c.confidence) < 0.7) reasons.push('confidence<0.7');
if (['urgent', 'high'].includes(c.priority)) reasons.push('priority=' + c.priority);
if ($json.is_unsure) reasons.push('model_unsure');

return {
  ...$json,
  ticket_id: c.ticket_id,
  classification_id: c.id,
  routed_to: reasons.length ? 'human_queue' : 'draft_review',
  routing_reason: reasons.join(', ') || 'confident, normal priority',
};
